CREATE OR REPLACE FUNCTION public.internet_claim_job(p_job_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_job public.internet_collection_jobs%ROWTYPE; BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'Not authorized'; END IF; SELECT * INTO v_job FROM public.internet_collection_jobs WHERE id=p_job_id FOR UPDATE; IF NOT FOUND OR v_job.state NOT IN ('queued','error') OR EXISTS (SELECT 1 FROM public.internet_collection_jobs j WHERE j.account_id=v_job.account_id AND j.id<>v_job.id AND j.lease_until>now() AND j.state NOT IN ('completed','error','intervention_required')) THEN RETURN false; END IF; UPDATE public.internet_collection_jobs SET state='logging_in',attempt=attempt+1,phase_sequence=phase_sequence+1,lease_until=now()+interval '5 minutes',heartbeat_at=now(),phase_changed_at=now() WHERE id=p_job_id; UPDATE public.internet_collection_runs SET state='running',started_at=coalesce(started_at,now()) WHERE id=v_job.run_id AND state='queued'; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.internet_claim_job(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.internet_claim_job(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.internet_update_job_phase(p_job_id uuid,p_run_id uuid,p_account_id uuid,p_sequence bigint,p_state text,p_counts jsonb,p_error_code text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_job public.internet_collection_jobs%ROWTYPE; v_total integer; v_done integer; v_errors integer; BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'Not authorized'; END IF; SELECT * INTO v_job FROM public.internet_collection_jobs WHERE id=p_job_id AND run_id=p_run_id AND account_id=p_account_id FOR UPDATE; IF NOT FOUND OR v_job.lease_until IS NULL OR v_job.lease_until<now() OR v_job.state IN ('completed','error','intervention_required') OR p_sequence<=v_job.phase_sequence OR p_state NOT IN ('logging_in','collecting_contracts','collecting_invoices','downloading_documents','reconciling','completed','error','intervention_required') THEN RETURN false; END IF; UPDATE public.internet_collection_jobs SET state=p_state,phase_sequence=p_sequence,counts=coalesce(p_counts,'{}'::jsonb),error_code=p_error_code,phase_changed_at=now(),heartbeat_at=now(),lease_until=CASE WHEN p_state IN ('completed','error','intervention_required') THEN NULL ELSE now()+interval '5 minutes' END WHERE id=p_job_id; SELECT count(*),count(*) FILTER (WHERE state IN ('completed','error','intervention_required')),count(*) FILTER (WHERE state IN ('error','intervention_required')) INTO v_total,v_done,v_errors FROM public.internet_collection_jobs WHERE run_id=p_run_id; IF v_total>0 AND v_done=v_total THEN UPDATE public.internet_collection_runs SET state=CASE WHEN v_errors=0 THEN 'completed' WHEN v_errors=v_total THEN 'failed' ELSE 'partial' END,finished_at=now() WHERE id=p_run_id; END IF; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.internet_update_job_phase(uuid,uuid,uuid,bigint,text,jsonb,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.internet_update_job_phase(uuid,uuid,uuid,bigint,text,jsonb,text) TO service_role;